package com.findit.web;

import com.findit.model.*; import com.findit.repo.*; import jakarta.servlet.http.HttpSession; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api")
public class ItemController {
 private final ItemRepository items;private final UserRepository users;private final MessageRepository messages;private final Path uploadPath;
 public ItemController(ItemRepository i,UserRepository u,MessageRepository m,@Value("${findit.upload-dir}")String dir){items=i;users=u;messages=m;uploadPath=Paths.get(dir).toAbsolutePath().normalize();}
 private AppUser current(HttpSession s){Object id=s.getAttribute("uid");return id instanceof Long?users.findById((Long)id).orElse(null):null;}
 private Map<String,Object> dto(Item i){String file=i.getImageFilename();String image=file==null?"":(file.startsWith("demo-")?"/images/"+file:"/uploads/"+file);return Map.ofEntries(Map.entry("id",i.getId()),Map.entry("name",i.getName()),Map.entry("category",i.getCategory()),Map.entry("description",i.getDescription()),Map.entry("type",i.getType()),Map.entry("location",i.getLocation()),Map.entry("itemDate",i.getItemDate()),Map.entry("imageUrl",image),Map.entry("status",i.getStatus()),Map.entry("createdAt",i.getCreatedAt()),Map.entry("userId",i.getUser().getId()),Map.entry("postedBy",i.getUser().getName()),Map.entry("department",i.getUser().getDepartment()),Map.entry("claimedByName",i.getClaimedBy()==null?"":i.getClaimedBy().getName()),Map.entry("claimedAt",i.getClaimedAt()==null?"":i.getClaimedAt().toString()));}
 @GetMapping("/items") public List<Map<String,Object>> search(@RequestParam(required=false)String q,@RequestParam(required=false)String category,@RequestParam(required=false)String type,@RequestParam(required=false)String location,@RequestParam(required=false)String status){return items.search(blank(q),blank(category),blank(type),blank(location),blank(status)).stream().map(this::dto).toList();}
 @GetMapping("/items/{id}") public ResponseEntity<?> detail(@PathVariable Long id){return items.withPeopleById(id).<ResponseEntity<?>>map(i->ResponseEntity.ok(dto(i))).orElseGet(()->ResponseEntity.notFound().build());}
 @PostMapping(value="/items",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<?> create(@RequestParam String name,@RequestParam String category,@RequestParam String description,@RequestParam String type,@RequestParam String location,@RequestParam String itemDate,@RequestParam(required=false)MultipartFile image,HttpSession s){AppUser u=current(s);if(u==null)return unauthorized();if("FOUND".equals(type)&&!List.of("STAFF","ADMIN").contains(u.getRole()))return ResponseEntity.status(403).body(Map.of("error","Only campus staff can post found items."));try{Item i=new Item();fill(i,name,category,description,type,location,itemDate);i.setUser(u);i.setImageFilename(save(image));return ResponseEntity.ok(dto(items.save(i)));}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}catch(Exception e){return ResponseEntity.internalServerError().body(Map.of("error","Could not save the image."));}}
 @PutMapping(value="/items/{id}",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<?> update(@PathVariable Long id,@RequestParam String name,@RequestParam String category,@RequestParam String description,@RequestParam String type,@RequestParam String location,@RequestParam String itemDate,@RequestParam(required=false)MultipartFile image,HttpSession s){AppUser u=current(s);Item i=items.withPeopleById(id).orElse(null);if(u==null)return unauthorized();if(i==null)return ResponseEntity.notFound().build();if(!i.getUser().getId().equals(u.getId())&&!List.of("STAFF","ADMIN").contains(u.getRole()))return ResponseEntity.status(403).body(Map.of("error","Only the post owner or campus staff can edit this item."));if("FOUND".equals(type)&&!List.of("STAFF","ADMIN").contains(u.getRole()))return ResponseEntity.status(403).body(Map.of("error","Only campus staff can move an item to the found board."));try{fill(i,name,category,description,type,location,itemDate);String f=save(image);if(f!=null)i.setImageFilename(f);return ResponseEntity.ok(dto(items.save(i)));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error","Check the item fields and image."));}}
 @Transactional @DeleteMapping("/items/{id}") public ResponseEntity<?> delete(@PathVariable Long id,HttpSession s){AppUser u=current(s);Item i=items.withPeopleById(id).orElse(null);if(u==null)return unauthorized();if(i==null)return ResponseEntity.notFound().build();if(!i.getUser().getId().equals(u.getId())&&!u.getRole().equals("ADMIN"))return ResponseEntity.status(403).body(Map.of("error","You can only delete your own posts."));messages.deleteForItem(id);items.delete(i);return ResponseEntity.noContent().build();}
 @PatchMapping("/items/{id}/status") public ResponseEntity<?> status(@PathVariable Long id,@RequestBody Map<String,String>b,HttpSession s){AppUser u=current(s);Item i=items.withPeopleById(id).orElse(null);if(u==null)return unauthorized();if(i==null)return ResponseEntity.notFound().build();if(!i.getUser().getId().equals(u.getId())&&!List.of("STAFF","ADMIN").contains(u.getRole()))return ResponseEntity.status(403).body(Map.of("error","Only the post owner or campus staff can update this item."));String status=b.getOrDefault("status","");if(!List.of("OPEN","CLAIMED","RECOVERED","RETURNED").contains(status))return ResponseEntity.badRequest().body(Map.of("error","Invalid status."));if("CLAIMED".equals(status))return ResponseEntity.badRequest().body(Map.of("error","Claimed status can only be set by approving a student claim request."));i.setStatus(status);i.setClaimedBy(null);i.setClaimedAt(null);return ResponseEntity.ok(dto(items.save(i)));}
 @Transactional
 @PostMapping("/items/{id}/requests")
 public ResponseEntity<?> requestItem(@PathVariable Long id,@RequestBody Map<String,String> b,HttpSession session){
  AppUser student=current(session);if(student==null)return unauthorized();
  if(!"STUDENT".equals(student.getRole()))return ResponseEntity.status(403).body(Map.of("error","Only student accounts can send an item request."));
  Item item=items.withPeopleById(id).orElse(null);if(item==null)return ResponseEntity.notFound().build();
  if("CLAIMED".equals(item.getStatus()))return ResponseEntity.badRequest().body(Map.of("error","This item has already been claimed."));
  if(item.getUser().getId().equals(student.getId()))return ResponseEntity.badRequest().body(Map.of("error","This is your own item report."));
  boolean claim="FOUND".equals(item.getType())||"CLAIM".equals(b.get("requestType"));String intro=claim?"CLAIM REQUEST: ":"FOUND ITEM LEAD: ";
  if((claim&&messages.hasClaimFromSender(id,student.getId()))||(!claim&&messages.existsByItem_IdAndSender_IdAndMessageStartingWith(id,student.getId(),intro)))return ResponseEntity.badRequest().body(Map.of("error","You already sent a request about this item."));
  if(claim&&messages.hasPendingClaim(id))return ResponseEntity.badRequest().body(Map.of("error","A claim request is already waiting for campus approval."));
  String detail=blank(b.get("message"));if(detail==null)detail="";
  if(detail.length()>1200)return ResponseEntity.badRequest().body(Map.of("error","Keep the item details under 1200 characters."));
  String body;
  if(claim){
   String name=blank(b.get("claimantName")),email=blank(b.get("claimantEmail")),phone=blank(b.get("claimantPhone")),studentNumber=blank(b.get("studentNumber")),claimClass=blank(b.get("claimantClass")),section=blank(b.get("claimantSection")),passingYear=blank(b.get("passingYear"));
   if(name==null||email==null||claimClass==null||section==null||studentNumber==null||passingYear==null||phone==null)return ResponseEntity.badRequest().body(Map.of("error","Complete your name, campus email, class, section, SRN, passing year, and phone number."));
   if(!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))return ResponseEntity.badRequest().body(Map.of("error","Enter a valid campus email address."));
   if(!passingYear.matches("20[0-9]{2}|2100"))return ResponseEntity.badRequest().body(Map.of("error","Enter a valid year of passing."));
   if(phone.length()<7||phone.length()>30)return ResponseEntity.badRequest().body(Map.of("error","Enter a valid phone number."));
   body=intro+"Name: "+name+"\nEmail: "+email+"\nClass: "+claimClass+"\nSection: "+section+"\nSRN: "+studentNumber+"\nYear of passing: "+passingYear+"\nPhone: "+phone+"\nHow I can identify it: "+(detail.isBlank()?"Not provided":detail);
  }else body=intro+(detail.isBlank()?"I think I may have found this item. Please contact me.":detail);
  AppUser recipient=claim?users.findAll().stream().filter(u->List.of("STAFF","ADMIN").contains(u.getRole())).findFirst().orElse(item.getUser()):item.getUser();ContactMessage request=new ContactMessage();request.setItem(item);request.setSender(student);request.setRecipient(recipient);request.setMessage(body);if(claim)request.setClaimDecision("PENDING");messages.save(request);
  return ResponseEntity.ok(Map.of("message",claim?"Claim request submitted. Campus staff will review your details.":"Your found item lead was sent to the student."));
 }
 @PostMapping("/items/{id}/messages") public ResponseEntity<?> message(@PathVariable Long id,@RequestBody Map<String,String>b,HttpSession s){AppUser sender=current(s);if(sender==null)return unauthorized();Item item=items.withPeopleById(id).orElse(null);if(item==null)return ResponseEntity.notFound().build();String body=b.getOrDefault("message","").trim();if(body.isBlank()||body.length()>2000)return ResponseEntity.badRequest().body(Map.of("error","Message must be between 1 and 2000 characters."));if(item.getUser().getId().equals(sender.getId()))return ResponseEntity.badRequest().body(Map.of("error","You cannot message yourself."));ContactMessage m=new ContactMessage();m.setItem(item);m.setSender(sender);m.setRecipient(item.getUser());m.setMessage(body);messages.save(m);return ResponseEntity.ok(Map.of("message","Message sent to the poster."));}
 @GetMapping("/messages") public ResponseEntity<?> inbox(HttpSession s){
  AppUser u=current(s);if(u==null)return unauthorized();
  List<ContactMessage> records=new ArrayList<>(messages.forUser(u.getId()));
  if(List.of("STAFF","ADMIN").contains(u.getRole())){Set<Long> seen=new HashSet<>();records.forEach(m->seen.add(m.getId()));for(ContactMessage m:messages.allClaimRequests())if(seen.add(m.getId()))records.add(m);}
  records.sort(Comparator.comparing(ContactMessage::getCreatedAt).reversed());
  return ResponseEntity.ok(records.stream().map(this::messageDto).toList());
 }
 private Map<String,Object> messageDto(ContactMessage m){
  boolean claim=m.getMessage().startsWith("CLAIM REQUEST:");String decision=m.getClaimDecision();
  if(claim&&decision==null){if("CLAIMED".equals(m.getItem().getStatus()))decision=m.getItem().getClaimedBy()!=null&&m.getItem().getClaimedBy().getId().equals(m.getSender().getId())?"APPROVED":"CLOSED";else decision="PENDING";}
  return Map.ofEntries(Map.entry("id",m.getId()),Map.entry("itemId",m.getItem().getId()),Map.entry("itemName",m.getItem().getName()),Map.entry("itemType",m.getItem().getType()),Map.entry("itemStatus",m.getItem().getStatus()),Map.entry("sender",m.getSender().getName()),Map.entry("senderId",m.getSender().getId()),Map.entry("recipient",m.getRecipient().getName()),Map.entry("message",m.getMessage()),Map.entry("claimRequest",claim),Map.entry("claimStatus",claim?decision:""),Map.entry("claimedBy",m.getItem().getClaimedBy()==null?"":m.getItem().getClaimedBy().getName()),Map.entry("claimedAt",m.getItem().getClaimedAt()==null?"":m.getItem().getClaimedAt().toString()),Map.entry("reviewedBy",m.getClaimReviewedBy()==null?"":m.getClaimReviewedBy().getName()),Map.entry("reviewedAt",m.getClaimReviewedAt()==null?"":m.getClaimReviewedAt().toString()),Map.entry("createdAt",m.getCreatedAt()));
 }
 @Transactional @PostMapping("/messages/{id}/approve-claim") public ResponseEntity<?> approveClaim(@PathVariable Long id,HttpSession s){
  AppUser staff=current(s);if(staff==null)return unauthorized();if(!List.of("STAFF","ADMIN").contains(staff.getRole()))return ResponseEntity.status(403).body(Map.of("error","Campus staff must approve item claims."));
  ContactMessage request=messages.withDetails(id).orElse(null);if(request==null)return ResponseEntity.notFound().build();Item item=request.getItem();
  if(!request.getMessage().startsWith("CLAIM REQUEST:"))return ResponseEntity.badRequest().body(Map.of("error","This message is not an item claim request."));
  if("REJECTED".equals(request.getClaimDecision()))return ResponseEntity.badRequest().body(Map.of("error","This claim request was declined."));
  if("CLAIMED".equals(item.getStatus()))return ResponseEntity.badRequest().body(Map.of("error","This item has already been claimed."));
  item.setType("FOUND");item.setStatus("CLAIMED");item.setClaimedBy(request.getSender());item.setClaimedAt(java.time.Instant.now());items.save(item);
  request.setClaimDecision("APPROVED");request.setClaimReviewedBy(staff);request.setClaimReviewedAt(java.time.Instant.now());messages.save(request);
  return ResponseEntity.ok(Map.of("message","Claim approved. The item is now in Claimed, with the claimant and approval recorded."));
 }
 @Transactional @PostMapping("/messages/{id}/reject-claim") public ResponseEntity<?> rejectClaim(@PathVariable Long id,HttpSession s){
  AppUser staff=current(s);if(staff==null)return unauthorized();if(!List.of("STAFF","ADMIN").contains(staff.getRole()))return ResponseEntity.status(403).body(Map.of("error","Campus staff must review item claims."));
  ContactMessage request=messages.withDetails(id).orElse(null);if(request==null)return ResponseEntity.notFound().build();
  if(!request.getMessage().startsWith("CLAIM REQUEST:"))return ResponseEntity.badRequest().body(Map.of("error","This message is not an item claim request."));
  if("REJECTED".equals(request.getClaimDecision()))return ResponseEntity.badRequest().body(Map.of("error","This claim request was already declined."));
  if("CLAIMED".equals(request.getItem().getStatus()))return ResponseEntity.badRequest().body(Map.of("error","A claimed item cannot be declined."));
  request.setClaimDecision("REJECTED");request.setClaimReviewedBy(staff);request.setClaimReviewedAt(java.time.Instant.now());messages.save(request);
  return ResponseEntity.ok(Map.of("message","Claim request declined. The item remains available for another request."));
 }
 @GetMapping("/dashboard/items") public ResponseEntity<?> mine(HttpSession s){AppUser u=current(s);if(u==null)return unauthorized();return ResponseEntity.ok(items.byOwner(u.getId()).stream().map(this::dto).toList());}
 @GetMapping("/admin/users") public ResponseEntity<?> adminUsers(HttpSession s){AppUser u=current(s);if(u==null)return unauthorized();if(!u.getRole().equals("ADMIN"))return ResponseEntity.status(403).body(Map.of("error","Administrator access required."));return ResponseEntity.ok(users.findAll().stream().map(x->Map.of("id",x.getId(),"name",x.getName(),"email",x.getEmail(),"department",x.getDepartment(),"role",x.getRole())).toList());}
 private void fill(Item i,String n,String c,String d,String t,String l,String date){if(n.isBlank()||c.isBlank()||d.isBlank()||l.isBlank()||!List.of("LOST","FOUND").contains(t))throw new IllegalArgumentException("Complete all fields and choose Lost or Found.");i.setName(n.trim());i.setCategory(c.trim());i.setDescription(d.trim());i.setType(t);i.setLocation(l.trim());i.setItemDate(LocalDate.parse(date));}
 private String save(MultipartFile f)throws Exception{if(f==null||f.isEmpty())return null;if(f.getSize()>5*1024*1024)throw new IllegalArgumentException("Image must be 5 MB or smaller.");String type=f.getContentType();if(type==null||!List.of("image/jpeg","image/png","image/webp","image/gif").contains(type))throw new IllegalArgumentException("Upload a JPG, PNG, WEBP, or GIF image.");Files.createDirectories(uploadPath);String ext=switch(type){case "image/jpeg"->".jpg";case "image/png"->".png";case "image/webp"->".webp";default->".gif";};String filename=UUID.randomUUID()+ext;Files.copy(f.getInputStream(),uploadPath.resolve(filename));return filename;}
 private String blank(String s){return s==null||s.isBlank()?null:s.trim();}private ResponseEntity<?> unauthorized(){return ResponseEntity.status(401).body(Map.of("error","Please log in first."));}
}

